const BUSINESS_SECTORS=Object.freeze(['AI·데이터','ICT·소프트웨어','금융·핀테크','바이오·신약','헬스케어·의료','농생명·푸드','모빌리티·물류','로봇·자동화','반도체·전자','소재·부품·장비','에너지','환경·기후테크','콘텐츠·미디어','커머스·유통','교육·에듀테크','관광·레저','건설·부동산','생활·소비재','전문서비스','방산·우주·해양','기타']);
const TECHNOLOGY_TAGS=Object.freeze(['AI','빅데이터','SaaS','클라우드','IoT','로봇','블록체인','센서','디지털트윈','자율주행','AR·VR','바이오','신소재','배터리','기타']);
const MAX_TECHNOLOGY_TAGS=5,MAX_ONE_LINE_LENGTH=50;
const SAMPLE_BUSINESS_PROFILES={
 '넥스트팜':['농생명·푸드','AI 기반 스마트팜 생육관리 및 생산성 예측 솔루션',['AI','IoT','빅데이터']],
 '카본웨이브':['소재·부품·장비','탄소복합소재를 활용한 경량 모빌리티 부품 제조',['신소재']],
 '그린바이오랩':['바이오·신약','바이오 기반 친환경 기능성 소재 연구개발 및 생산',['바이오','신소재']],
 '모빌리온':['모빌리티·물류','전기차 배터리 상태 진단 및 수명 예측 관리 솔루션',['배터리','AI','센서']],
 '온유푸드':['농생명·푸드','지역 농산물을 활용한 대체 단백질 식품 개발 및 제조',['바이오']],
 '딥비전테크':['AI·데이터','제조 현장 불량 탐지와 품질 관리를 위한 AI 비전 검사 솔루션',['AI','빅데이터']],
 '에코루프':['환경·기후테크','폐자원 배출 기업과 재활용 기업을 연결하는 자원순환 플랫폼',['SaaS','빅데이터']],
 '메디센스':['헬스케어·의료','웨어러블 센서 기반 건강 모니터링 및 이상 신호 분석 서비스',['센서','IoT','AI']],
 '루트로보틱스':['로봇·자동화','제조 현장 작업 자동화를 위한 협동 로봇 및 통합 제어 솔루션',['로봇','센서']],
 '블루하버':['농생명·푸드','수질·생육 데이터 기반 친환경 수산 양식 관리 솔루션',['IoT','빅데이터']],
 '솔라브릿지':['에너지','분산형 태양광 발전 설비 모니터링 및 에너지 관리 솔루션',['IoT','클라우드']],
 '로컬인사이트':['AI·데이터','지역 상권·소비 데이터 분석을 통한 입지 및 경영 의사결정 서비스',['빅데이터','AI']]
};
function standardizeBusiness(c){const sample=SAMPLE_BUSINESS_PROFILES[c.name],untouched=sample&&!c.owner&&c.businessSchemaVersion!==2;const old=c.businessSector||c.sector||'';const aliases={'AI·SW':'AI·데이터','첨단소재':'소재·부품·장비','미래모빌리티':'모빌리티·물류','로봇·제조':'로봇·자동화','바이오·헬스':sample?.[0]||'헬스케어·의료','에너지·환경':sample?.[0]||'환경·기후테크'};const businessSector=untouched?sample[0]:BUSINESS_SECTORS.includes(old)?old:aliases[old]|| (old?'기타':'');const oneLineDescription=untouched?sample[1]:c.oneLineDescription??c.summary??'';const technologyTags=[...new Set(untouched?sample[2]:Array.isArray(c.technologyTags)?c.technologyTags:[])].filter(t=>TECHNOLOGY_TAGS.includes(t)).slice(0,MAX_TECHNOLOGY_TAGS);return {...c,legacyBusinessSector:c.legacyBusinessSector||(!BUSINESS_SECTORS.includes(old)?old:''),businessSchemaVersion:2,companyName:c.name||c.companyName||'',businessSector,oneLineDescription,technologyTags,technologyOther:technologyTags.includes('기타')?c.technologyOther||'':'',representativeName:c.ceo||c.representativeName||'',location:c.headOffice||c.city||c.location||'',investmentStage:c.stage||c.investmentStage||'',sector:businessSector,summary:oneLineDescription};}
function technologyText(c){return (c.technologyTags||[]).map(t=>t==='기타'&&c.technologyOther?'기타: '+c.technologyOther:t).join(' · ');}
function technologyInput(c){return `<fieldset class="technology-input full"><legend>기술 태그 <span class="optional">선택 · 최대 5개</span></legend><div class="technology-choices">${TECHNOLOGY_TAGS.map(t=>`<label class="technology-chip"><input type="checkbox" name="technologyTags" value="${esc(t)}" ${(c.technologyTags||[]).includes(t)?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div><p class="smallnote" id="technology-count" role="status"></p><div id="technology-other" ${(c.technologyTags||[]).includes('기타')?'':'hidden'}>${profileField('기타 기술 설명','technologyOther',c.technologyOther||'',{optional:true,length:20,placeholder:'기술명 또는 짧은 설명, 최대 20자'})}</div></fieldset>`;}
function bindTechnology(form){const choices=[...form.querySelectorAll('[name="technologyTags"]')];function sync(){const selected=choices.filter(c=>c.checked);choices.forEach(c=>c.disabled=selected.length>=MAX_TECHNOLOGY_TAGS&&!c.checked);$('#technology-count').textContent=selected.length+' / '+MAX_TECHNOLOGY_TAGS+'개 선택';$('#technology-other').hidden=!selected.some(c=>c.value==='기타');}choices.forEach(c=>c.addEventListener('change',sync));sync();}
function sectorFilterMenu(){return `<details class="sort-picker sector-filter" id="sector-filter"><summary aria-label="사업 분야 필터"><span>${esc(sectorFilter||'전체 사업 분야')}</span><span class="chevron"></span></summary><div class="sort-options"><span class="menu-caption">사업 분야</span>${['',...BUSINESS_SECTORS].map(s=>`<button class="sort-option ${sectorFilter===s?'selected':''}" aria-pressed="${sectorFilter===s}" onclick="chooseSector('${s}')">${s||'전체'}${sectorFilter===s?'<span aria-hidden="true">✓</span>':''}</button>`).join('')}</div></details>`;}
function chooseSector(value){sectorFilter=value;page=1;home();$('#sector-filter summary')?.focus();}
const INVESTMENT_STAGES=Object.freeze(['투자유치 전','Seed','Pre-A','Series A','Series B','Series C','Series D 이상','Pre-IPO','IPO']);
function stageFilterMenu(){return '<details class="sort-picker sector-filter" id="stage-filter"><summary aria-label="투자 단계 필터"><span>'+esc(stageFilter||'전체 투자 단계')+'</span><span class="chevron"></span></summary><div class="sort-options"><span class="menu-caption">투자 단계</span>'+['',...INVESTMENT_STAGES].map(s=>'<button class="sort-option '+(stageFilter===s?'selected':'')+'" aria-pressed="'+(stageFilter===s)+'" onclick="chooseStage(\''+s+'\')">'+(s||'전체')+(stageFilter===s?'<span aria-hidden="true">✓</span>':'')+'</button>').join('')+'</div></details>';}
function chooseStage(value){stageFilter=value;page=1;home();$('#stage-filter summary')?.focus();}
window.addEventListener('click',e=>{const p=document.querySelector('#stage-filter');if(p&&!p.contains(e.target))p.open=false;});
window.addEventListener('keydown',e=>{const p=document.querySelector('#stage-filter');if(e.key==='Escape'&&p?.open){p.open=false;p.querySelector('summary').focus();}});
function refreshSampleCompany(c){const names=Object.keys(SAMPLE_BUSINESS_PROFILES),i=names.indexOf(c.name);if(i<0||c.owner||c.submittedAt||c.mockVersion===18)return c;const individual=i===11;const headquarters=(c.city||'전주시')+' 예시로 '+(10+i)+' (가상 주소)';const workplaces=[{type:'본점',address:headquarters,detail:(i+2)+'층'}];if([1,4,8].includes(i))workplaces.push({type:'공장',address:'군산시 가상산업로 '+(20+i),detail:'A동'},{type:'공장',address:'익산시 가상산업로 '+(30+i),detail:'B동'});if([0,2,7].includes(i))workplaces.push({type:'연구소',address:'전주시 가상연구로 '+(40+i),detail:'연구동'});return {...c,mockVersion:18,entityType:individual?'individual':'corporate',legalForm:individual?'':i===9?'유한회사':'주식회사',businessNo:'000-00-'+String(i+1).padStart(5,'0'),corporateNo:individual?'':'000000-'+String(i+1).padStart(7,'0'),founded:(2017+i%6)+'-03-15',representatives:[{name:c.ceo,birthDate:(1978+i)+'-05-12'},...(i===0?[{name:'이서연',birthDate:'1985-09-21'}]:[])],ceo:c.ceo+(i===0?', 이서연':''),headOffice:headquarters,headOfficeDetail:(i+2)+'층',workplaces,investmentUnit:'million',raised:String([1800,800,300,2500,600,400,1000,200,700,300,2000,0][i]),stage:i===11?'투자유치 전':c.stage,employmentBasis:'new',annuals:Object.fromEntries([2023,2024,2025].map((year,j)=>[year,{revenue:(i+1)*80+j*100,employment:2+i%4+j,investment:i===11?0:j===2?(i+1)*100:0}])),irName:'',visible:c.visible};}
function companyFilterPanel(){
 const group=(title,key,values,current)=>'<div class="filter-line"><h2>'+title+'</h2><div class="filter-buttons" role="group" aria-label="'+title+'">'+values.map(([v,l],i)=>'<button type="button" id="filter-'+key+'-'+i+'" class="filter-choice '+(current===v?'selected':'')+'" aria-pressed="'+(current===v)+'" onclick="setCompanyFilter(\''+key+'\',\''+v+'\','+i+')">'+esc(l)+'</button>').join('')+'</div></div>';
 return '<section class="company-filter-panel" aria-label="기업 검색 조건">'+group('사업 분야','sector',[['','전체'],...BUSINESS_SECTORS.map(x=>[x,x])],sectorFilter)+group('투자 단계','stage',[['','전체'],...INVESTMENT_STAGES.map(x=>[x,x])],stageFilter)+group('정렬 기준','sort',[['latest','최근 등록 순'],['name','기업명 순']],sort)+'<div class="filter-bottom"><span>각 항목에서 하나씩 선택할 수 있습니다.</span><button type="button" class="filter-reset" onclick="resetCompanyFilters()">조건 초기화 ↺</button></div></section>';
}
function setCompanyFilter(key,value,index){if(key==='sector')sectorFilter=value;else if(key==='stage')stageFilter=value;else if(key==='sort')sort=value;page=1;$('#company-filters').innerHTML=companyFilterPanel();listContent();$('#filter-'+key+'-'+index)?.focus();}
function resetCompanyFilters(){sectorFilter='';stageFilter='';sort='latest';page=1;$('#company-filters').innerHTML=companyFilterPanel();listContent();$('.filter-reset')?.focus();}

function companyRegisteredTime(c){const explicit=Date.parse(c.createdAt);if(Number.isFinite(explicit))return explicit;const id=Number(c.id);if(id>1000000000000&&id<8640000000000000)return id;const sample=Object.keys(SAMPLE_BUSINESS_PROFILES).indexOf(c.name);if(sample>=0)return Date.UTC(2026,8,1+sample);return Date.parse(c.submittedAt)||0;}
